template:
fn flatten_positives(data: &[Vec<i32>]) -> Vec<i32> {
    data.iter()
        .⟦slot1⟧(|row| row.iter())
        .⟦slot2⟧(|&&x| x > 0)
        .copied()
        .collect()
}

fn main() {
    let grid = vec![vec![1, -2], vec![3, 4]];
    println!("{:?}", flatten_positives(&grid));
}

tests:
#[test]
fn flattens_and_filters() {
    let grid = vec![vec![1, -2], vec![3, 4]];
    assert_eq!(flatten_positives(&grid), vec![1, 3, 4]);
}

#[test]
fn handles_empty_rows() {
    let grid: Vec<Vec<i32>> = vec![vec![], vec![-1, -2], vec![5]];
    assert_eq!(flatten_positives(&grid), vec![5]);
}
